// Original exercises. A row contains an explanation, a complete practical procedure and a measurable exit test.
type Row=[string,Category,string,string,string,string,string,string];
const deep: Row[][] = [
 [
 ['Minimalny nacisk, czysty dźwięk','Technika','Czysty dźwięk wymaga kontaktu struny z progiem, nie ściskania całego gryfu. Szukanie minimalnego nacisku ułatwi później akordy.','Zagraj F na 1/1, kładąc palec tuż za progiem.|Stopniowo zmniejszaj nacisk do brzęczenia, potem dodaj tylko tyle, by dźwięk był czysty.|Powtórz na 2/1 i 3/2; po każdej próbie całkowicie rozluźnij dłoń.','1/1 oznacza: struna 1, próg 1. Docisk → odpuszczenie → czysty dźwięk.','Wydobądź po pięć czystych dźwięków w trzech miejscach.|Po każdej serii potrafisz od razu rozluźnić kciuk.','Ból jest sygnałem do przerwy, nie kryterium skutecznego treningu.','technique'],
 ['Tirando i apoyando','Technika','Tirando kończy ruch palca poza sąsiednią struną; w apoyando palec opiera się na sąsiedniej, grubszej strunie. Oba sposoby służą kontroli brzmienia.','Zagraj osiem dźwięków E na strunie 1 tirando.|Powtórz apoyando, opierając palec na strunie 2 bez uderzania w nią.|Zagraj E–F–G–F, porównując oba sposoby przy 50 BPM.','i–m tirando → i–m apoyando; kciuk pozostaje swobodny.','Zagraj motyw dwoma sposobami i nazwij różnicę.|Sąsiednia struna nie wydaje przypadkowego dźwięku.','Nie wpychaj całej dłoni w struny. Zmienia się tor ruchu palca.','technique'],
 ['Puls wewnętrzny: klik i cisza','Rytm','Metronom sprawdza puls, ale nie powinien być jedynym powodem, dla którego wiesz, kiedy zagrać. Liczenie trwa także w ciszy.','Ustaw 60 BPM i licz cztery takty na głos.|W następnym takcie graj tylko na 1 i 3, licząc pozostałe pulsy.|Zatrzymaj metronom na cztery liczone pulsy i uruchom ponownie; porównaj własne tempo.','1 graj · 2 licz · 3 graj · 4 licz.','Zagraj osiem taktów bez przyspieszania pauz.|Po ciszy wracasz na właściwy numer pulsu.','Nie traktuj przypadkowego momentu uruchomienia metronomu jako testu idealnej synchronizacji. Oceniaj tempo.','meter'],
 ['Przejście przez trzy struny','Technika','Zmiana struny jest osobną umiejętnością. Oko patrzy na cel, a dłoń wykonuje mały ruch, bez odrywania ramienia.','Na pustych strunach 1, 2 i 3 zagraj po dwa dźwięki i–m.|Wróć 3–2–1 przy 50 BPM.|Zmień wzór na po trzy dźwięki na strunę; zachowaj naprzemienność także na granicy.','1: i m i · 2: m i m · 3: i m i.','Wykonaj cztery obiegi obu wzorów.|Nie powtarzasz palca przy każdej zmianie struny.','Nie przyspieszaj przejścia, aby ukryć brak kontroli.','technique'],
 ['Dźwięk, pauza i wyciszenie','Rytm','Pauza oznacza zaplanowaną ciszę. Na gitarze często trzeba ją wykonać ruchem tłumiącym, bo struna sama nadal brzmi.','Zagraj pustą strunę 1 na 1 i dotknij jej delikatnie na 2.|Zagraj na 3 i wycisz na 4; powtarzaj przy 60 BPM.|Zagraj dźwięk trwający dwa pulsy, potem dwa pulsy ciszy.','| E cisza E cisza | E — cisza cisza |','Zagraj osiem taktów z równymi pauzami.|Wyciszenie nie produkuje dodatkowego szarpnięcia.','Nie zaciskaj lewej ręki, gdy możesz wyciszyć strunę prawą.','meter'],
 ['Ucz się frazy, nie szeregu progów','Słuch','Rozpoznawalna melodia ma kierunek i zakończenie. Głos pomaga zapamiętać ją jako całość, nawet zanim poznasz nazwy wszystkich nut.','Zagraj na strunie 1 progi 0–1–3–1, po jednej ćwierćnucie.|Zaśpiewaj ten sam kierunek bez gitary.|Zagraj z pamięci, następnie zmień ostatni dźwięk na 0 i porównaj zakończenia.','E F G F → E F G E; cztery pulsy na frazę.','Odtwórz oba warianty po krótkiej przerwie.|Potrafisz zanucić kierunek przed zagraniem.','Nie oceniaj swojego głosu jak występu. To sposób sprawdzenia pamięci muzycznej.','ear'],
 ],
 [
 ['Osiem akordów otwartych','Technika','E, Em, A, Am, D, Dm, C i G tworzą bazę wielu akompaniamentów. Nie muszą być opanowane w jeden dzień.','Porównaj E 022100 z Em 022000 oraz A x02220 z Am x02210.|Dodaj D xx0232 i Dm xx0231; sprawdź osobno każdą strunę.|Przez kolejne sesje losuj po cztery z ośmiu chwytów i wracaj do C oraz G.','Od struny 6 do 1: x = nie graj, 0 = pusta struna.','Ustaw wszystkie osiem akordów z pamięci, bez wymogu szybkości.|W każdym chwycie słychać wszystkie zamierzone struny.','W D i Dm nie uderzaj wszystkich sześciu strun.','chordmap'],
 ['Palec prowadzący i wspólne dźwięki','Technika','Wspólny palec może skrócić zmianę, ale tylko jeśli pasuje do obu chwytów. Inne palce poruszają się jednocześnie.','Zmieniaj Am x02210 na C x32010, pozostawiając palec na 2/1.|Sprawdź wolno, które pozostałe palce muszą zmienić miejsce.|Zagraj po dwa pulsy Am i C przez osiem taktów przy 50 BPM.','Am → C: wspólne 2/1 i 4/2, zmienia się bas.','Zagraj osiem taktów bez dodatkowego pulsu na zmianę.|Potrafisz wyjaśnić, który palec pozostaje na miejscu.','Nie utrzymuj na siłę palca, jeśli blokuje wygodną pozycję dłoni.','technique'],
 ['Zmiany akordów pod zegarem','Technika','Licznik zmian jest narzędziem obserwacji, nie wyścigiem. Licz tylko chwyt, który rzeczywiście zabrzmiał czysto.','Wybierz trudną parę, np. C–G. Przez minutę zmieniaj i delikatnie uderzaj każdy chwyt.|Zapisz liczbę czystych zmian oraz błąd, który pojawia się najczęściej.|Ćwicz sam ruch przez dwie minuty, następnie sprawdź ponownie przy równym pulsie.','Sesja 1: liczba czystych zmian; sesja 2: porównanie przy tym samym tempie.','Zagraj tę parę w ośmiu taktach przy 50 BPM, zmiana co dwa pulsy.|W dwóch sesjach utrzymujesz czystość, nie tylko większą liczbę.','Nie zaliczaj bezgłośnego ułożenia palców jako czystej zmiany.','practice'],
 ['Ręka rytmiczna nie zatrzymuje się','Rytm','Ruch dłoni wyznacza podział czasu także wtedy, gdy nie dotyka strun. To przygotowanie do rytmów z opuszczonym uderzeniem.','Na Em poruszaj dłonią dół–góra w równych ósemkach przy 50 BPM.|Dotykaj strun tylko w dół, ruch w górę wykonuj w powietrzu.|Dodaj uderzenie w górę po 2 i 4; policz na głos każdy podział.','1 i 2 i 3 i 4 i: dół – dół góra dół – dół góra.','Utrzymaj wzór przez osiem taktów.|Zmiana na Am nie zatrzymuje ruchu dłoni.','Nie usztywniaj nadgarstka i nie uderzaj paznokciem z dużą siłą.','beginner'],
 ['Mapa piosenki: zwrotka i refren','Repertuar','Znajomość czterech chwytów nie wystarcza, jeśli gubisz ich kolejność. Prosta mapa sekcji zmniejsza obciążenie pamięci.','Wybierz jedną z piosenek rozdziału i obejrzyj demonstrację nauczyciela.|Zapisz symbole sekcji A i B oraz liczbę obiegów akordów w każdej.|Zagraj akompaniament, śledząc mapę; zaznacz miejsce, w którym zwykle się mylisz.','A × 2 → B × 2 → A → B; to przykład formy, nie zapis konkretnej piosenki.','Zagraj wybraną sekwencję sekcji od początku do końca.|Wiesz, który akord rozpoczyna każdą sekcję.','Nie przenoś przykładowej formy na utwór bez sprawdzenia jego lekcji.','marty'],
 ['Próba ciągła po pomyłce','Repertuar','Na próbie fragmentu poprawiasz błędy. W próbie ciągłej ćwiczysz utrzymanie czasu i powrót w następnym takcie. To dwa różne zadania.','Zagraj osiem taktów Em–Am–C–G po dwa takty na akord.|Jeśli pomylisz chwyt, pomiń uderzenie i wróć na początek następnego taktu.|Po zakończeniu wybierz jedną trudną zmianę, popraw ją osobno i wykonaj drugi przebieg.','Ćwiczenie szczegółu → próba całości → jedna poprawka → całość.','Wykonaj dwa przebiegi bez restartowania od początku.|Potrafisz wskazać jeden poprawiony problem.','Kontynuowanie nie znaczy ignorowania błędów w każdej sesji.','practice'],
 ],
 [
 ['Szesnastki bez pośpiechu','Rytm','Cztery szesnastki mieszczą się w jednym pulsie ćwierćnutowym. Wolne tempo pozwala usłyszeć równość podziału.','Ustaw 40 BPM i powiedz cztery równe sylaby na klik.|Zagraj na pustej strunie 1 cztery dźwięki i–m na puls.|Przeplataj takt ćwierćnut, ósemek i szesnastek bez zmiany metronomu.','Na jeden klik: 1 dźwięk → 2 dźwięki → 4 dźwięki.','Wykonaj cztery cykle trzech podziałów.|Każdy kolejny takt zaczyna się razem z pulsem.','Nie przyspieszaj całego pulsu, gdy zwiększa się liczba nut.','meter'],
 ['Triole i metrum 6/8','Rytm','W 6/8 zwykle czujesz dwa duże pulsy, każdy z trzema ósemkami. To inne grupowanie niż trzy pulsy po dwie ósemki w 3/4.','Policz 1–2–3, 4–5–6, akcentując 1 i 4.|Na Em zagraj sześć pojedynczych strun, grupując je w dwa pulsy.|Porównaj z 3/4, akcentując 1, 3 i 5 w tym samym szeregu sześciu ósemek.','6/8: RAZ dwa trzy CZTERY pięć sześć.','Zagraj osiem taktów 6/8 z dwoma akcentami.|Usłysz różnicę względem trzech grup po dwie.','BPM musi określać, czy klika ósemka, czy duży puls. Zapisz to w notatce.','meter'],
 ['Przedtakt: wejście przed jedynką','Rytm','Melodia może zacząć się przed pierwszym pełnym taktem. Wtedy jej pierwszy dźwięk nie jest automatycznie pierwszym pulsem.','Odlicz 1–2–3–4, zagraj E na 4, następnie G na kolejnym 1.|Powtórz, zostawiając dwa pełne takty między wejściami.|Znajdź przedtakt w wybranej melodii i zaznacz go w notatce.','… 1 2 3 E | G — — — |','Wejdź poprawnie pięć razy po pełnym odliczeniu.|Nie dodajesz dodatkowego pulsu przed pierwszym pełnym taktem.','Nie licz od nowa od 1 przy każdym usłyszanym początku frazy.','meter'],
 ['Nuty na trzech górnych strunach','Teoria','Czytanie zaczyna się od małego obszaru gryfu. Dźwięk powinien łączyć nazwę, zapis i miejsce, a nie tylko liczbę progu.','Znajdź E F G na strunie 1, B C D na 2 i G A na 3.|Zapisz po cztery nuty w kluczu wiolinowym, korzystając z lekcji o pięciolinii.|Następnego dnia czytaj je w innej kolejności i graj bez dopisywania tabulatury.','1: 0 1 3 · 2: 0 1 3 · 3: 0 2.','Odczytaj osiem z dziesięciu losowych nut w tym zakresie.|Zagraj czteronutowy zapis bez patrzenia na tabulaturę.','Ten sam dźwięk może mieć kilka miejsc na gryfie. Tu celowo ograniczamy pozycję.','theory'],
 ['Akcent zmienia charakter riffu','Rytm','Riff może mieć te same wysokości i zupełnie inny charakter, gdy przesuniesz akcent. Puls nadal pozostaje stały.','Zagraj osiem równych E naprzemiennie i–m.|W pierwszej wersji zaakcentuj pierwszy i piąty dźwięk, w drugiej trzeci i siódmy.|Przenieś oba warianty na motyw E–G–A–G, powtarzany ósemkami.','Ósemki: >E G A G >E G A G; potem E G >A G E G >A G.','Zagraj po cztery takty obu wersji.|Akcent jest głośniejszy, ale nie dłuższy.','Nie zatrzymuj palca przed akcentem, bo rozciągniesz rytm.','technique'],
 ['Łączenie riffu z akompaniamentem','Repertuar','Najtrudniejszy punkt piosenki bywa między sekcjami. Ćwiczenie samego riffu nie przygotowuje ruchu do akordu.','Wybierz riff z repertuaru lub własny E–G–A–G.|Zagraj dwa takty riffu, potem dwa takty Em ćwierćnutami.|Ćwicz osobno ostatni puls riffu i pierwszy akord, a następnie połącz cztery obiegi.','Riff 2 takty → Em 2 takty → powrót bez pauzy technicznej.','Zagraj cztery obiegi przy 55 BPM.|Potrafisz rozpocząć także od części akordowej.','Pauza muzyczna jest zaplanowana; przerwa na szukanie chwytu nie jest.','marty'],
 ],
 [
 ['B, H i dźwięki enharmoniczne','Teoria','W tej aplikacji B oznacza polskie H, a B♭ polskie B. C♯ i D♭ na gitarze temperowanej mają ten sam próg, ale różne funkcje w zapisie.','Na strunie 2 zagraj B na 0 i C na 1.|Na strunie 5 znajdź B♭ na 1 oraz B na 2.|Zapisz skalę D-dur z C♯, nie D♭; każda litera pojawia się raz.','Międzynarodowe: A B♭ B C · polskie: A B H C.','Przetłumacz pięć nazw B/H/B♭ bez pomyłki.|Pokaż na gryfie jedną parę enharmoniczną.','Nie nazywaj C♯ i D♭ dwiema różnymi wysokościami w standardowym stroju.','major'],
 ['Sekundy, seksty i septymy','Słuch','Rozszerz zestaw interwałów dopiero po tercjach i kwintach. Seksta i septyma to większy skok, ale nadal można go usłyszeć oraz odnaleźć.','Od C na 5/3 zagraj D na 4/0, A na 3/2 i B na 2/0.|Porównaj 2, 9 i 11 półtonów w warsztacie.|Zaśpiewaj odpowiedź i ułóż trzy frazy, każdą z innym skokiem.','C–D: sekunda wielka; C–A: seksta wielka; C–B: septyma wielka.','Rozpoznaj 8/10 prób z ograniczonego zestawu.|Znajdź każdy z trzech interwałów od nowej podstawy.','Najpierw określ liczbę liter, potem jakość interwału.','intervals'],
 ['Interwał harmoniczny i przewrót','Teoria','Interwał melodyczny brzmi kolejno, harmoniczny jednocześnie. Przeniesienie dolnego dźwięku oktawę wyżej zmienia interwał w jego przewrót.','Zagraj C na 3/5 oraz E na 2/5 kolejno i razem.|Przenieś C na 1/8: para E–C tworzy sekstę małą.|Porównaj F–B oraz B–F i nazwij odległości.','Tercja wielka C–E → seksta mała E–C; liczby sumują się do 9.','Zagraj i nazwij przewroty tercji oraz kwinty.|Rozróżnij słuchem granie kolejno od współbrzmienia.','Przewrót interwału nie jest zmianą trybu akordu.','intervals'],
 ['Ta sama nuta w kilku miejscach','Technika','Na gitarze jedna wysokość ma kilka palcowań. Wybór pozycji wpływa na barwę oraz łatwość następnego ruchu.','Znajdź E4 na 1/0, 2/5 i 3/9.|Zagraj krótką melodię E–F–G na strunie 1, potem na 2: progi 5–6–8.|Porównaj barwę i wybierz palcowanie ułatwiające powrót do C na strunie 2.','E4: 1/0 = 2/5 = 3/9; ta sama wysokość, inna struna.','Zagraj motyw w dwóch miejscach bez zmiany melodii.|Uzasadnij jeden wybór palcowania.','Nie myl tej samej nazwy w innej oktawie z tą samą wysokością.','technique'],
 ['Znaki przykluczowe: G i D','Teoria','Znaki przy kluczu obowiązują przez cały utwór, dopóki nie zostaną zmienione. Budowa skali pozwala je sprawdzić bez zgadywania.','Zbuduj G-dur od wzoru tonów i półtonów; zaznacz F♯.|Zbuduj D-dur, zaznacz F♯ i C♯.|Zagraj po cztery dźwięki każdej skali w wygodnej pozycji i zaśpiewaj tonikę.','G A B C D E F♯ G · D E F♯ G A B C♯ D.','Zapisz obie skale bez pominięcia znaku.|Znajdź F♯ i C♯ w dwóch miejscach gryfu.','Nie przenoś automatycznie wszystkich pustych strun do dowolnej tonacji.','major'],
 ['Funkcje I, IV i V w piosence','Teoria','Cyfry rzymskie opisują stopień, na którym budujesz akord. W tonacji durowej I, IV i V są durowe i pozwalają usłyszeć ruch od toniki do napięcia i powrotu.','Zagraj C–Fmaj7–G–C i nazwij podstawy C, F, G.|Porównaj z G–C–D–G, zachowując czas trwania akordów.|W wybranej piosence zaznacz tonikę i dominantę, jeśli występują.','C: I=C, IV=F, V=G · G: I=G, IV=C, V=D.','Zagraj ten sam ruch w dwóch tonacjach.|Wyjaśnij, że Fmaj7 jest tu łatwym wariantem IV z dodaną septymą.','Pierwszy akord utworu nie musi być toniką. Sprawdź zakończenie i brzmienie.','cadences'],
 ],
 [
 ['Pentatonika durowa i molowa','Teoria','C-dur i a-moll mają wspólne dźwięki pentatoniki, ale inne centrum. Ten sam zbiór nie oznacza tego samego wrażenia zakończenia.','Zagraj C–D–E–G–A nad akordem C.|Zagraj A–C–D–E–G nad Am.|Ułóż dwie frazy z tych samych dźwięków: jedną kończąc na C, drugą na A.','C-dur: 1 2 3 5 6 · a-moll: 1 ♭3 4 5 ♭7.','Wykonaj dwie frazy o różnych centrach.|Zaśpiewaj tonikę po każdym akordzie.','Nie przesuwaj tylko kształtu, nie wiedząc, gdzie jest tonika.','major'],
 ['Ograniczenie: tylko rytm i pauza','Improwizacja','Ograniczenia pozwalają ocenić jeden element muzyki. Przy trzech wysokościach łatwiej usłyszeć, czy fraza rzeczywiście coś opowiada.','Wybierz A, C i E; ustaw 60 BPM.|Zagraj cztery takty, w każdym zostaw cały puls ciszy.|Zagraj kolejne cztery, zachowując rytm, ale zmieniając kolejność dźwięków.','A – C E | pauza A — —; – oznacza podtrzymanie.','Zagraj osiem taktów bez dodania czwartego dźwięku.|Potrafisz powtórzyć jeden z rytmów po zakończeniu.','Losowa cisza wynikająca z szukania progu nie jest zaplanowaną pauzą.','ear'],
 ['Fraza rozpoczynająca się po jedynce','Rytm','Solo nie musi zaczynać się razem z każdym taktem. Późniejsze wejście zostawia miejsce dla akompaniamentu.','Odlicz takt i zacznij A–C–E dopiero na 2.|W kolejnej próbie zacznij na „i” po 2, licząc ósemki.|Po każdej frazie zostaw takt ciszy i wróć w zaplanowanym miejscu.','1 i 2 [i: A] 3:C i 4:E i.','Wykonaj po cztery wejścia obu wariantów.|Wiesz, gdzie jest 1 także podczas ciszy.','Nie skracaj taktu, aby kolejna fraza zaczęła się natychmiast.','meter'],
 ['Przesunięcie palca: slide','Technika','Slide łączy dwa dźwięki jednym ruchem po strunie. Na nylonie ważniejsze są czyste końce i rytm niż głośny szum między progami.','Zagraj A na 3/2 i przesuń palec do C na 3/5.|Wróć z C do A, nie dociskając mocniej w ruchu.|Wpleć slide w cztery takty, docierając do celu na 3.','1: A, 2: ruch, 3: C, 4: cisza.','Traf do progu docelowego osiem razy przy 50 BPM.|Dźwięk końcowy jest czysty, bez nadmiernego napięcia.','Nie przyspieszaj ruchu bez określenia, na który puls ma dotrzeć cel.','technique'],
 ['Dwie frazy nad dwoma akordami','Improwizacja','Już dwa akordy wystarczą, aby odpowiedź zmieniała się wraz z harmonią. Nad Am wybierz C lub E, nad C wybierz E lub G.','Zagraj Am przez dwa takty, potem C przez dwa.|Po każdym akordzie zagraj krótką odpowiedź kończącą się na wybranym składniku.|Wykonaj cztery obiegi i zmień zakończenia, zachowując rytm.','Am → D–C; C → A–G.','Każda odpowiedź kończy się na dźwięku bieżącego akordu.|Potrafisz nazwać cztery użyte zakończenia.','Nie oceniaj dopasowania tylko po tym, że wszystkie dźwięki pochodzą z tej samej skali.','triads'],
 ['Zapamiętaj własne solo','Słuch','Improwizacja może zostawić materiał do kompozycji. Wybranie i odtworzenie najlepszej frazy uczy świadomego słownika muzycznego.','Zaimprowizuj osiem taktów i wybierz najlepsze dwa.|Zapisz rytm słowami oraz nazwy dźwięków lub progi.|W następnej sesji odtwórz frazę, potem zmień tylko jedną nutę.','Pomysł → zapis → pamięć → wariacja.','Odtwórz własną frazę w kolejnej sesji.|Pokaż oryginał i jedną rozpoznawalną wariację.','Nie zapisuj wyłącznie nazw nut bez ich długości.','practice'],
 ],
 [
 ['Sześć wzorów arpeggia','Technika','Ten sam akord można rozłożyć na wiele porządków. Zmiana wzoru ma być świadoma, a nie efektem gubienia palców.','Na Am zagraj p–i–m–a oraz p–a–m–i po cztery cykle.|Dodaj p–i–a–m i p–m–i–a, utrzymując równe ćwierćnuty.|Dodaj sześciodźwiękowe p–i–m–a–m–i oraz p–a–m–i–m–a.','p na 5, i na 3, m na 2, a na 1; 4 lub 6 dźwięków w cyklu.','Zagraj każdy wzór cztery razy przy 50 BPM.|Nazwij wzór przed rozpoczęciem.','Nie wciskaj sześciu ćwierćnut w takt 4/4. Dla sześciu dźwięków licz 6/8.','technique'],
 ['Małe barré przed arpeggiem','Technika','Przy F xx3211 jeden palec obejmuje tylko struny 1 i 2. To przygotowanie do repertuaru, bez konieczności pełnego barré.','Ustaw sam palec wskazujący na 1/1 i 2/1, sprawdź każdą strunę.|Dodaj 3/2 oraz 4/3 i zagraj F od struny 4.|Zmieniaj Am–F po dwa takty, po każdej serii rozluźniając dłoń.','F: x x 3 2 1 1; nie graj strun 6 i 5.','Zagraj cztery czyste arpeggia F.|Połącz Am–F przez osiem taktów w wolnym tempie.','Nie obejmuj wszystkich strun, jeśli zadanie wymaga tylko dwóch.','technique'],
 ['Przygotowanie palców prawej dłoni','Technika','Planting oznacza przygotowanie palca na strunie przed szarpnięciem. Pomaga w kontroli, ale może przerwać wybrzmiewanie, jeśli zastosujesz je zbyt wcześnie.','Na pustych strunach przygotuj i–m–a na 3–2–1 i zagraj kolejno.|Powtórz, przygotowując każdy palec tuż przed jego dźwiękiem.|Porównaj obie wersje na Am i wybierz tę, która zachowuje zamierzone legato.','Przygotuj → szarpnij → słuchaj długości poprzedniej nuty.','Zagraj cztery cykle bez szukania strun.|Umiesz pokazać, kiedy przygotowanie tłumi potrzebny dźwięk.','Nie zamieniaj planting w obowiązek kładzenia wszystkich palców po każdym dźwięku.','technique'],
 ['Bas podtrzymany przez cały takt','Technika','Głosy mają własne długości. Bas może trwać cztery pulsy, chociaż melodia zmienia się na każdym z nich.','Zagraj E na pustej strunie 6 wraz z E na 1/0.|Dodaj melodię F–G–E na pulsach 2–3–4, nie dotykając basu.|W następnym takcie zmień bas na A, a melodię na C–D–C–B.','Bas E cały takt / góra E F G E; bas A / góra C D C B.','Zagraj osiem taktów z pełną długością basu.|Tłumisz poprzedni bas przy wejściu nowego, jeśli współbrzmienie przeszkadza.','Nie myl długiego basu z głośnym basem.','bach'],
 ['Legato w środku arpeggia','Technika','Hammer-on i pull-off mogą działać nad wybrzmiewającym basem. Kluczowa jest równa głośność i brak dodatkowego ruchu kciuka.','Zagraj bas A na 5/0 i C na 2/1.|Dodaj hammer-on do D na 2/3, zachowując bas.|W kolejnym takcie zagraj D, pull-off do C i zakończ E na 1/0.','Bas: A — — —; góra: C D — E.','Połącz cztery pary taktów przy 50 BPM.|Ozdobnik nie jest głośniejszy od głównej melodii.','Pull-off jest kontrolowanym ruchem, nie pionowym oderwaniem palca.','technique'],
 ['Melodia, bas i środkowy głos','Technika','W fakturze trzygłosowej nie wszystkie nuty są jednakowo ważne. Górna linia zwykle prowadzi, bas wspiera, a wypełnienie pozostaje w tle.','Na Em zagraj p na 6, i na 3, m na 2 i a na 1.|Zagraj osiem cykli, wyróżniając wyłącznie a.|Następnie świadomie wyróżnij bas, porównaj i wróć do prowadzenia melodii.','Melodia: wyraźna · bas: obecny · środek: cichy.','Słyszysz różnicę między trzema poziomami głośności.|Zachowujesz ten balans także na Am.','Nie próbuj osiągnąć kontrastu samym przyspieszeniem melodii.','roman'],
 ],
 [
 ['Sus2 i sus4 w otwartej pozycji','Teoria','W sus tercję zastępuje sekunda albo kwarta. Taki akord nie ma tercji określającej dur lub moll; nie zawsze musi natychmiast się rozwiązać.','Zagraj D xx0232, Dsus2 xx0230 i Dsus4 xx0233.|Nazwij górne dźwięki F♯, E i G.|Ułóż cztery takty D–Dsus4–D–Dsus2, zmieniając tylko potrzebny palec.','D: D F♯ A · Dsus2: D E A · Dsus4: D G A.','Zagraj cztery cykle bez zatrzymania.|Wyjaśnij, dlaczego sus4 nie oznacza dodania czwartego dźwięku do pełnej triady.','Nie myl sus2 z add9, który zachowuje tercję.','chordmap'],
 ['Pryma nie zawsze jest basem','Teoria','Nazwa akordu wynika z jego budowy, a nie zawsze z najniższego dźwięku. C/E nadal zawiera C–E–G, lecz E jest w basie.','Zagraj C x32010 i C/E 032010.|Wypisz składniki obu chwytów od najniższej struny.|Porównaj G 320003 i G/B x20003 w przejściu C–G/B–Am.','C/E: pryma C, bas E. G/B: pryma G, bas B.','Zagraj progresję z opadającym basem C–B–A.|Nazwij niezależnie prymę i bas każdego chwytu.','Nie stosuj zasady „najniższa nuta daje nazwę akordu” do przewrotów.','inversions'],
 ['Triady na strunach 1–2–3','Teoria','Małe triady pozwalają zobaczyć składniki akordu i prowadzić głosy krótkimi ruchami. Trzy struny wystarczą do pełnej triady.','Zagraj C: struny 3/5, 2/5, 1/3.|Zagraj F: 3/5, 2/6, 1/5 oraz G: 3/4, 2/3, 1/3.|Nazwij każdy dźwięk, potem graj C–F–G–C po dwa pulsy na chwyt.','C: C E G · F: C F A · G: B D G.','Zagraj cztery obiegi przy 50 BPM.|Wskaż prymę, tercję i kwintę w każdym układzie.','Układ palców to skutek budowy akordu, nie zamiennik jej znajomości.','triads'],
 ['Trzy rodzaje septymy w praktyce','Teoria','Cmaj7, C7 i Cm7 różnią się tercją oraz septymą. Sam symbol 7 oznacza akord dominantowy, nie dowolny akord z czterech nut.','Zapisz Cmaj7 C–E–G–B, C7 C–E–G–B♭ i Cm7 C–E♭–G–B♭.|Zagraj składniki kolejno w wygodnych miejscach gryfu.|Porównaj proste chwyty Cmaj7 x32000, C7 x32310 oraz Am7 x02010 jako inny przykład m7.','maj7: 1 3 5 7 · 7: 1 3 5 ♭7 · m7: 1 ♭3 5 ♭7.','Zbuduj trzy jakości od C na kartce i jako arpeggio.|Rozpoznaj różnicę Cmaj7 i C7 po usłyszeniu obu.','Nie oceniaj jakości akordu wyłącznie jako „wesoły” albo „smutny”.','sevenths'],
 ['Akord z ruchomego kształtu','Technika','Przesunięty kształt E lub A zmienia akord, ponieważ przesuwa się jego pryma. Puste struny trzeba wtedy zastąpić barré lub pominąć.','Zagraj F 133211 i G 355433, odnajdując prymy na strunie 6.|Porównaj Bm x24432 i Cm x35543 z prymą na 5.|Ćwicz po dwa chwyty, z pełnym rozluźnieniem między seriami.','Kształt Em + barré na V = Am; pryma na 6/5.','Nazwij cztery przesunięte chwyty bez liczenia od początku gryfu.|Zagraj je czysto w krótkiej serii, bez bólu.','Nie utrzymuj barré podczas przerwy ani nie naciskaj maksymalną siłą.','chordmap'],
 ['Transpozycja akompaniamentu bez kapodastra','Teoria','Transpozycja zachowuje relacje stopni, ale zmienia wysokość toniki. Umiejętność przydaje się do dopasowania akompaniamentu do głosu.','Zapisz C–Am–F–G jako I–vi–IV–V.|Przenieś do G: G–Em–C–D.|Zagraj obie wersje z tym samym rytmem, a potem zanuć melodię o stopniach 3–2–1.','C-dur → G-dur; duże cyfry dur, małe moll.','Zagraj cztery obiegi w obu tonacjach.|Wyjaśnij, dlaczego Am zmienia się na Em, a nie E.','Nie przesuwaj każdej nazwy o przypadkową liczbę liter bez sprawdzenia jakości.','major'],
 ],
 [
 ['Moll naturalne, harmoniczne i melodyczne','Teoria','W a-moll naturalnym jest G, w harmonicznym G♯. W klasycznym ćwiczeniu melodycznego podnosi się F i G w górę, a wraca naturalnym w dół. To materiał, nie nakaz dla każdej melodii.','Zagraj A–B–C–D–E–F–G–A.|Zmień G na G♯ i posłuchaj prowadzenia do A.|Porównaj F♯–G♯–A z F–G–A i użyj obu jako zakończeń krótkiej frazy.','Naturalna: 1 2 ♭3 4 5 ♭6 ♭7; harmoniczna: podniesiony VII.','Zagraj trzy warianty i nazwij zmienione dźwięki.|Wybierz G♯ nad E7 prowadzącym do Am.','Jazzowe użycie moll melodycznej może zachowywać podniesione stopnie w obu kierunkach.','minor'],
 ['Połącz dwie pozycje pentatoniki','Technika','Łączenie pozycji ma pozwolić kontynuować frazę, a nie uruchamiać kolejny mechaniczny schemat. Wspólny dźwięk jest punktem przejścia.','Zagraj A–C–D–E na strunie 3: 2–5–7–9.|Znajdź te same dźwięki w niższej pozycji na strunach 5–4.|Ułóż frazę, która przechodzi przez wspólne E, i wróć inną drogą.','A C D E G; przejście może wypaść na długim E.','Zagraj tę samą frazę w dwóch pozycjach.|Wykonaj trzy płynne przejścia bez dodatkowej nuty.','Nie przesuwaj ręki przypadkowo podczas szybkiego przebiegu.','technique'],
 ['Arpeggia przez zmianę akordu','Improwizacja','Arpeggio solowe ukazuje harmonię pojedynczymi dźwiękami. Najbliższy składnik następnego akordu często daje płynniejszy ruch niż powrót do prymy.','Zagraj A–C–E–G dla Am7, następnie D–F–A–C dla Dm7.|Połącz E z F oraz G z A przez granicę taktów.|Ułóż osiem taktów, rozpoczynając kolejne akordy od tercji.','Am7: A C E G → Dm7: D F A C; E→F to półton.','Zagraj cztery zmiany z różnymi najbliższymi celami.|Nazwij funkcję dźwięku na początku każdego akordu.','Nie traktuj arpeggia wyłącznie jako ćwiczenia od dołu do góry.','sevenths'],
 ['Blues: tercja mała i wielka','Słuch','W bluesie napięcie między tercją małą i wielką jest środkiem wyrazu. Na nylonie można je pokazać półtonowym ruchem bez szerokiego podciągania struny.','Nad A7 x02020 porównaj C na 2/1 i C♯ na 2/2.|Zagraj C–C♯–E, potem E–C–A.|Wstaw oba motywy w pierwsze cztery takty bluesa A.','A7 zawiera C♯; C jest ekspresyjnym napięciem, które możesz rozwiązać.','Zagraj dwie frazy z celowym rozwiązaniem C→C♯.|Słyszysz różnicę napięcia i stabilnego zakończenia.','Nie wymuszaj rockowych bendów na klasycznej gitarze.','intermediate'],
 ['Transkrypcja rytmu przed wysokością','Słuch','Krótki fragment jest łatwiejszy do odtworzenia, gdy rozdzielisz rytm i wysokość. Zwolnione odtwarzanie pomaga, ale ostatecznie wróć do zwykłego tempa.','Wybierz 2–4 sekundy melodii z dostępnej lekcji repertuarowej.|Wyklaszcz rytm, potem znajdź pierwszy i ostatni dźwięk.|Uzupełnij środek, porównaj z filmem i zapisz poprawkę.','Najpierw puls i długości → skrajne dźwięki → reszta frazy.','Odtwórz krótki fragment zgodnie z rytmem i wysokościami.|Przenieś go o ton wyżej, zachowując relacje.','Nie transkrybuj całego solo naraz; jeden dokładny fragment wystarczy.','ear'],
 ['Solo ma formę i kulminację','Improwizacja','Rozwój solo może wynikać z gęstości rytmu, rejestru i dynamiki. Kulminacja potrzebuje kontrastu z wcześniejszym spokojem.','Zaplanuj 16 taktów: 4 oszczędne, 4 z wariacją, 4 intensywniejsze, 4 zamykające.|Użyj jednego motywu i najwyższy dźwięk zostaw na trzecią część.|Zagraj plan nad znaną harmonią, potem opisz, czy kulminacja była słyszalna.','A → A′ → kontrast → powrót; nie rosnące tempo.','Wykonaj 16 taktów z rozpoznawalnym łukiem.|Końcowa fraza reaguje na ostatni akord.','Więcej nut w każdej kolejnej sekundzie nie jest jedynym sposobem budowania napięcia.','practice'],
 ],
 [
 ['Akordy add9, 9 i 13','Teoria','Add9 dodaje nonę do triady bez obowiązkowej septymy. Symbol 9 zwykle zakłada septymę, a 13 określa dalsze rozszerzenie; na gitarze część składników się pomija.','Zapisz Cadd9 C–E–G–D i C9 C–E–G–B♭–D.|Zagraj Cadd9 x32030 i C7 x32310, słuchając różnicy.|Zapisz G13 jako G–B–D–F–A–C–E i wybierz szkielet G–B–F–E do ćwiczenia pojedynczymi nutami.','Cadd9 ≠ C9; 9 to 2 o oktawę wyżej.','Wyjaśnij różnicę add9 i 9.|Zagraj składniki wybranego uproszczonego akordu 13.','Nie próbuj pomieścić siedmiu różnych dźwięków na sześciu strunach.','chordmap'],
 ['Prowadzenie głosów bez dużych skoków','Teoria','W harmonizacji ważny jest ruch poszczególnych linii. Wspólny dźwięk można zatrzymać, a pozostałe poprowadzić o sekundę.','Zagraj triady C, F i G z rozdziału 7 na górnych strunach.|Zapisz ruch każdej struny między C a F.|Ułóż cztery akordy z możliwie małym ruchem górnego głosu i zagraj wolno.','C–E–G → C–F–A: wspólne C, E→F, G→A.','Wskaż wspólny dźwięk i dwa ruchome głosy.|Zagraj progresję bez przypadkowych przerw w melodii.','Najbliższy układ nie zawsze jest najlepszy: sprawdź wygodę i brzmienie.','voicing'],
 ['Synkopa przez kreskę taktową','Rytm','Dźwięk rozpoczęty przed mocną częścią i podtrzymany przez nią przesuwa odczuwany akcent. Wewnętrzny puls musi trwać mimo braku uderzenia na 1.','Licz ósemki przy 50 BPM.|Zagraj Em na „i” po 4 i pozwól mu brzmieć przez 1 następnego taktu.|Dodaj bas na 3 i powtórz cztery razy, cały czas licząc.','… 4 [i: akord] | 1 — 2 — 3 bas 4 …','Utrzymaj osiem taktów bez dodatkowego uderzenia na 1.|Potrafisz wyklaskać wzór bez gitary.','Nie przesuwaj całego taktu razem z akcentem.','meter'],
 ['Chord melody: najpierw szkielet','Repertuar','Aranżację solo buduj od melodii i najważniejszych basów. Pełny akord na każdej nucie często utrudnia czytelność.','Wybierz osiem taktów znanej melodii i zagraj samą górną linię.|Dodaj tylko prymę akordu na początku taktu, zmieniając oktawę w razie potrzeby.|W dwóch miejscach dodaj tercję lub kwintę pod długą nutą melodii.','Melodia → basy na 1 → dwa wybrane wypełnienia.','Zagraj osiem taktów rozpoznawalnej melodii z basem.|Żadne wypełnienie nie przerywa głównej frazy.','Nie próbuj od razu skopiować wielogłosowej aranżacji koncertowej.','voicing'],
 ['Modalność przez dźwięk charakterystyczny','Teoria','Tryb słyszysz względem centrum, nie od samego rozpoczęcia skali na innej nucie. Dorycki od a-moll naturalnego różni się F♯ zamiast F.','Zagraj bas A i porównaj frazy A–C–D–F–E oraz A–C–D–F♯–E.|Zakończ obie na A, aby zachować centrum.|Ułóż osiem taktów, w których F♯ jest świadomym kolorem, nie przypadkową pomyłką.','A dorycka: A B C D E F♯ G; centrum A.','Rozróżnij oba warianty po porównaniu.|Pokaż charakterystyczną sekstę wielką A–F♯.','Nie nazywaj G-dur zagranej od A automatycznie dorycką muzyką bez centrum A.','minor'],
 ['Własny wstęp i zakończenie','Repertuar','Aranżacja staje się spójna, gdy wstęp przygotowuje tonację i puls, a zakończenie domyka formę. Nie musi to być popis techniczny.','Do wybranej piosenki dopisz dwutaktowy wstęp oparty na ostatnim akordzie i motywie melodii.|Dodaj zakończenie: dominanta, tonika i świadome wyciszenie.|Zagraj wstęp, jedną sekcję i zakończenie bez przerw.','Przygotowanie → temat → kadencja → cisza.','Wstęp prowadzi do właściwego wejścia melodii.|Zakończenie jest zaplanowane i możliwe do powtórzenia.','Nie dodawaj efektownego intro, które jest trudniejsze niż cały utwór.','cadences'],
 ],
 [
 ['Analiza przed pierwszą próbą','Teoria','Analiza powinna ułatwiać granie. Tonacja, forma, kadencje i zmiany pozycji mówią, gdzie poświęcić czas.','Wybierz utwór finałowy i przejrzyj lekcję oraz dostępny zapis.|Zanotuj tonację, metrum, sekcje i trzy trudne miejsca.|Dla każdego miejsca zaplanuj jedno krótkie ćwiczenie, zamiast powtarzać całość.','Problem: zmiana pozycji → ćwiczenie: ostatnia nuta przed zmianą + pierwsza po zmianie.','Masz mapę utworu i trzy konkretne ćwiczenia.|Potrafisz wskazać miejsce największego napięcia harmonicznego.','Analiza nie jest przepisywaniem wszystkich nazw nut do notatki.','practice'],
 ['Pamięć w punktach orientacyjnych','Technika','Pamięć wyłącznie ruchowa bywa krucha. Osobne punkty startowe pozwalają wrócić do muzyki po pomyłce.','Wybierz początki trzech fraz w utworze.|Zagraj każdą od razu, bez poprzedzającego fragmentu.|W następnej sesji losuj kolejność i nazwij akord lub tonację miejsca startu.','Start A → start C → start B, bez rozbiegu.','Rozpocznij od trzech punktów w dwóch różnych dniach.|Po celowej przerwie wróć od najbliższej frazy.','Nie ćwicz pamięci wyłącznie przez odtwarzanie od pierwszego taktu.','practice'],
 ['Interpretacja: plan frazy i rubato','Repertuar','Rubato jest świadomą elastycznością czasu. Najpierw potrzebujesz stabilnego pulsu, aby odróżnić interpretację od potknięcia technicznego.','Zagraj frazę z metronomem i zaplanuj szczyt dynamiki.|Bez metronomu delikatnie poszerz zakończenie, utrzymując ciągłość melodii.|Powtórz tę samą interpretację, a następnie porównaj z wersją równą.','Początek spokojny → kierunek do szczytu → odprężenie.','Potrafisz powtórzyć ten sam plan frazy.|Zwolnienie nie pojawia się wyłącznie w trudnym technicznie miejscu.','Nie maskuj każdej pomyłki słowem rubato.','roman'],
 ['Kompozycja z ograniczeniami','Improwizacja','Ograniczona forma ułatwia ukończenie pomysłu. Kontrast nie musi oznaczać nowej techniki: może zmienić się rytm lub rejestr.','Napisz temat A ośmiu taktów z jednym motywem.|Dopisz B ośmiu taktów, zmieniając rytm lub harmonię, a potem wróć do A.|Zapisz melodię i akordy na tyle dokładnie, by odtworzyć utwór jutro.','A (8) – B (8) – A (8); zakończenie na wybranej tonice.','Zagraj całą miniaturę 24 taktów.|Odtwórz ją następnego dnia bez ponownego komponowania.','Nie poprawiaj bez końca pierwszych dwóch taktów kosztem ukończenia formy.','cadences'],
 ['Próba generalna bez zatrzymań','Repertuar','Próba występu obejmuje także wejście, oddech, ciszę między utworami i reakcję na pomyłkę. To osobna umiejętność.','Przygotuj trzy pozycje: utwór, własną aranżację i krótką improwizację.|Nastrój gitarę, ustaw kolejność i wykonaj wszystko w jednej próbie.|Po zakończeniu zapisz tylko trzy najważniejsze poprawki, potem ćwicz je osobno.','Wejście → utwór → cisza → aranżacja → improwizacja → zakończenie.','Wykonaj próbę od początku do końca bez restartu.|Następna próba zawiera co najmniej jedną konkretną poprawę.','Nie oceniaj całego występu na podstawie jednego zabrzęczenia.','practice'],
 ['Twój następny cykl nauki','Teoria','Samodzielność oznacza umiejętność wyboru problemu, metody i sprawdzianu. Kolejny etap powinien wynikać z muzyki, którą chcesz grać.','Wybierz dwa utwory na następne cztery tygodnie i jedną odnogę.|Rozpisz tydzień: trzy sesje pracy, jedna powtórka, jedna próba całości.|Ustal mierzalne kryterium, np. pełna sekcja z równym basem, i sprawdź je po tygodniu.','Utwór → brakująca umiejętność → małe ćwiczenie → sprawdzian → korekta planu.','Masz plan tygodnia i kryterium dla obu utworów.|Potrafisz zmniejszyć zakres zadania, gdy okazuje się za trudne.','Brak szybkiego zaliczenia nie oznacza braku nauki. Dopasuj wielkość kroku.','practice'],
 ],
];

type Side=[number,string,Row];
const side:Side[]=[
 [1,'Klasyka',['Barwa przy mostku i otworze','Technika','Miejsce szarpnięcia zmienia barwę bez zmiany wysokości. Ucho prowadzi dłoń do wybranego koloru.','Zagraj E nad otworem rezonansowym.|Przesuń prawą dłoń bliżej mostka i porównaj.|Wykonaj cztery krótkie frazy, zmieniając miejsce dopiero między nimi.','Ta sama nuta, dwa kolory: miękki i jasny.','Odtwórz oba kolory bez zmiany tempa.','Nie zwiększaj siły, próbując uzyskać jaśniejszą barwę.','technique']],
 [1,'Słuch i czytanie',['Echo dwóch dźwięków','Słuch','Pamięć wysokości trenuje się w małych porcjach. Wystarczy krótka przerwa między wzorem a odpowiedzią.','Zagraj E–G na pierwszej strunie.|Odczekaj cztery pulsy i zanuć parę.|Odtwórz ją, potem sprawdź E–F oraz G–E.','Wzór → 4 pulsy ciszy → głos → gitara.','Powtórz poprawnie cztery z pięciu par.','Nie zamieniaj tego ćwiczenia w bezmyślne powtarzanie ruchu bez słuchania.','ear']],
 [1,'Klasyka',['Palcowanie zapisane na przyszłość','Technika','Cyfry 1–4 opisują palce lewej dłoni, a p–i–m–a prawej. Stałe palcowanie ułatwia pamięć.','Zapisz progi 0–1–3–1 dla pierwszej struny.|Dopisz palce lewej ręki: 0–1–3–1 i prawej i–m–i–m.|Zagraj pięć razy identycznie, a jutro sprawdź odczyt.','Lewa 1 = wskazujący, 4 = mały; prawa a = serdeczny.','Odczytaj swój zapis po przerwie i wykonaj go bez zmiany palców.','Numer struny, progu i palca to trzy różne informacje.','classical']],
 [2,'Blues',['Dominanty otwarte E7, A7 i B7','Technika','Trzy otwarte akordy septymowe pozwolą później zagrać bluesa. Na razie celem jest ich czyste brzmienie.','Sprawdź E7 020100 i A7 x02020 pojedynczymi strunami.|Dodaj B7 x21202 bez struny 6.|Zagraj E7–A7–B7–E7 po jednym takcie przy 45 BPM.','E7 → A7 → B7 → E7, po cztery spokojne uderzenia.','Zagraj cztery obiegi z czystymi chwytami.','B7 wymaga przygotowania kilku palców; nie ucz się go w pośpiechu.','sevenths']],
 [2,'Fingerstyle',['Kciuk zamiast bicia','Technika','Akompaniament może zaczynać się od samego basu. Pryma akordu pomaga usłyszeć harmonię nawet bez pełnego chwytu.','Na Em graj pustą 6, na Am pustą 5.|Dodaj C na 5/3 oraz G na 6/3.|Zagraj po cztery równe basy każdego akordu.','Em: E · Am: A · C: C · G: G.','Zagraj 16 taktów z równą głośnością basów.','Nie szarp kciukiem tak mocno, by struna uderzała o progi.','technique']],
 [2,'Słuch i czytanie',['Dur i moll w porównaniu','Słuch','Porównanie akordów od tej samej podstawy izoluje zmianę tercji. Em i E różnią się jednym dźwiękiem w chwycie.','Zagraj Em, potem E, słuchając struny 3.|Zaśpiewaj G oraz G♯ osobno.|Powtórz z Am i A, po czym opisz różnicę własnymi słowami.','Em → E: G → G♯; Am → A: C → C♯.','Wskaż zmieniony dźwięk w obu parach.','Dur nie musi oznaczać wesołej muzyki, a moll smutnej.','triads']],
 [3,'Blues',['Rytm shuffle na jednym akordzie','Rytm','Podział długi–krótki wyrasta z trioli. Zachowaj wspólny puls także przy zmianie z prostych ósemek.','Powiedz tri-o-la na każdy klik przy 50 BPM.|Zagraj pierwszy i trzeci element na E7.|Przeplataj dwa takty shuffle i dwa takty prostych ósemek.','Tri (cisza) la → tri (cisza) la.','Wykonaj cztery przejścia między podziałami bez zmiany pulsu.','Nie graj przypadkowo nierównych ósemek zamiast świadomej trioli.','meter']],
 [3,'Klasyka',['Walc: bas i dwa akordy','Rytm','W prostym walcu bas na 1 pomaga usłyszeć początek taktu, a lżejsze akordy wypełniają 2 i 3.','Na Am zagraj kciukiem strunę 5 na 1.|Na 2 i 3 szarp razem struny 3–2–1.|Zmieniaj Am–Em co dwa takty i graj cicho na 2 oraz 3.','1 bas · 2 akord · 3 akord.','Zagraj osiem taktów 3/4 bez dodawania czwartego pulsu.','Nie akcentuj jednakowo wszystkich trzech części taktu.','meter']],
 [3,'Słuch i czytanie',['Dyktando czterech taktów rytmu','Słuch','Zapis rytmu może zacząć się od słów i kresek. Ważne, aby zapis dawał się wykonać po przerwie.','Wymyśl cztery takty z ćwierćnut, ósemek i pauz.|Zapisz pod każdym numer pulsu i „i”.|Po przerwie wyklaszcz zapis, a potem zagraj go na E.','1 i 2 i 3 i 4 i — siatka ośmiu miejsc.','Odtwórz swój zapis następnego dnia bez dopowiadania brakującego pulsu.','Nie pomijaj pauz w zapisie tylko dlatego, że nie słychać w nich nuty.','meter']],
 [4,'Jazz i bossa',['Przewroty triady na jednej strunie','Teoria','Przewrót zmienia najniższy składnik, zachowując zestaw dźwięków. Możesz najpierw poznać go jako melodię.','Zagraj kolejno C–E–G.|Przenieś C oktawę wyżej i zagraj E–G–C.|Zagraj G–C–E, porównując wszystkie trzy układy.','C E G → E G C → G C E.','Nazwij podstawową postać oraz dwa przewroty.','Nie zmieniaj C-dur w inny akord tylko dlatego, że zaczyna się od E.','inversions']],
 [4,'Słuch i czytanie',['Interwały w dół','Słuch','Rozpoznawanie skoku w dół nie zawsze przenosi się automatycznie z ćwiczeń w górę. Ćwicz oba kierunki osobno.','Zagraj G–E, G–C oraz E–C.|Policz półtony i nazwij interwały.|Zaśpiewaj każdą parę od innego wygodnego dźwięku, potem sprawdź na gryfie.','G→E: tercja mała w dół; G→C: kwinta czysta w dół.','Odtwórz trzy różne skoki w dół po ich usłyszeniu.','Kierunek nie zmienia liczby półtonów tej samej pary wysokości.','intervals']],
 [4,'Klasyka',['Czytanie bez zatrzymania','Technika','Czytanie a vista wymaga łatwiejszego materiału niż utwór ćwiczony tygodniami. Patrz odrobinę przed aktualny dźwięk.','Napisz osiem prostych taktów nut na strunach 1–3.|Odłóż zapis do następnego dnia, przejrzyj rytm przed startem.|Zagraj raz przy 40 BPM i nie wracaj do pomyłek do końca próby.','Przejrzyj → odlicz → czytaj → dopiero potem popraw.','Przejdź cały zapis z zachowaniem liczby pulsów.','Nie wybieraj do czytania utworu, który jest na granicy Twojej techniki.','classical']],
 [5,'Blues',['Blue note jako przejście','Improwizacja','Obniżona kwinta może zwiększać napięcie między kwartą a kwintą. Użyj jej celowo w krótkim ruchu.','Zagraj D–E♭–E na strunie 4 progach 0–1–2.|Dołącz C i A z pentatoniki.|Ułóż dwa motywy, raz przechodząc szybko przez E♭, raz zatrzymując je na chwilę.','A C D E♭ E → C A.','Zagraj oba warianty i wskaż miejsce rozwiązania napięcia.','Nie dodawaj blue note do każdego taktu tylko dlatego, że ją znasz.','intermediate']],
 [5,'Fingerstyle',['Akord i odpowiedź bez podkładu','Improwizacja','Na jednej gitarze można prowadzić rozmowę akordu z melodią. Cisza między nimi jest częścią aranżacji.','Zagraj Am na 1, pozwól mu wybrzmieć na 2.|Na 3 i 4 zagraj C–E.|W drugim takcie odpowiedz E–C–A, potem powtórz z nowym rytmem.','Akord → oddech → dwie nuty → odpowiedź.','Zagraj osiem taktów z czterema różnymi odpowiedziami.','Nie próbuj podtrzymać pełnego chwytu, jeśli blokuje prostą melodię.','triads']],
 [5,'Słuch i czytanie',['Zaśpiewaj tercję akordu','Słuch','Tercja mówi wiele o jakości akordu. Usłyszenie jej przed graniem pomaga celować we frazie.','Zagraj C, znajdź i zaśpiewaj E.|Zagraj Am, znajdź i zaśpiewaj C.|Powtórz dla G oraz Em, sprawdzając odpowiedź gitarą.','C→E · Am→C · G→B · Em→G.','Traf tercję w trzech z czterech akordów po krótkim namyśle.','Możesz śpiewać w wygodnej oktawie; liczy się nazwa i relacja.','ear']],
 [6,'Fingerstyle',['Travis: cztery niezależne basy','Technika','Kciuk może grać wszystkie ćwierćnuty, a palce wypełniać przestrzenie. Najpierw stabilny bas, dopiero później gęstość.','Na C graj 5–4–5–4 kciukiem przy 45 BPM.|Dodaj strunę 2 po 1 i strunę 1 po 3.|Powtórz na Am, potem zmieniaj chwyt co dwa takty.','1:p5 i:m2 2:p4 3:p5 i:a1 4:p4.','Zagraj osiem taktów bez zaburzenia kciuka.','Nie przyspieszaj basu przy dodawaniu palców pomiędzy pulsami.','technique']],
 [6,'Klasyka',['Flażolety XII, VII i V','Technika','Węzły drgającej struny dają różne składowe harmoniczne. Dotykasz nad progiem, nie dociskasz do podstrunnicy.','Wydobądź flażolet nad XII progiem struny 1.|Porównaj VII i V, szarpiąc bliżej mostka.|Wpleć trzy flażolety jako zakończenie krótkiego arpeggia.','XII: oktawa · VII: oktawa i kwinta · V: dwie oktawy.','Uzyskaj czyste dźwięki w trzech miejscach.','Przy V progu potrzebna jest precyzja dotyku, nie większy nacisk.','technique']],
 [6,'Klasyka',['Tremolo: pierwszy równy cykl','Technika','Tremolo p–a–m–i jest osobną koordynacją. Wolny, równy cykl przygotowuje ją lepiej niż szybka nierówna seria.','Zagraj p na 5, a–m–i na 1, po jednym dźwięku na klik 50 BPM.|Po ośmiu cyklach graj po dwa dźwięki na klik.|Porównaj głośność a, m oraz i i wróć do wolniejszej wersji, jeśli się rozjeżdża.','p a m i | p a m i; trzy palce na tej samej strunie.','Zagraj 16 równych cykli bez narastającego napięcia.','Nie uznawaj tego wstępu za gotowość do Recuerdos de la Alhambra.','technique']],
 [7,'Jazz i bossa',['Szkielety akordów: tercja i septyma','Teoria','Shell voicing pomija część dźwięków, zachowując informację o jakości. Pryma może być zagrana osobno jako bas.','Zapisz tercję i septymę Dm7: F–C, G7: B–F, Cmaj7: E–B.|Znajdź każdą parę na dwóch sąsiednich strunach.|Zagraj bas, potem parę, po jednym takcie na akord.','Dm7 → G7 → Cmaj7: słuchaj ruchu C→B i F→E.','Wykonaj cztery kadencje i nazwij wszystkie pary.','Nie pomijaj tercji i septymy tylko po to, aby zachować znany chwyt.','sevenths']],
 [7,'Blues',['Blues dwudźwiękami','Technika','Dwudźwięk prymy i kwinty daje otwarte brzmienie bez tercji. Jest przydatny także na gitarze klasycznej, bez przesteru.','Zagraj E na 6/0 i B na 5/2 jednocześnie.|Zostaw E i przesuń B na C♯ na 5/4.|Przeplataj obie pary ćwierćnutami, potem w shuffle.','E–B → E–C♯; kwinta przechodzi w sekstę.','Zagraj osiem taktów bez przypadkowego uderzania innych strun.','Nie rozciągaj palców na siłę; przerwij, jeśli ruch jest niewygodny.','intermediate']],
 [7,'Jazz i bossa',['Dim7 i półzmniejszony','Teoria','Akord zmniejszony septymowy i półzmniejszony różnią się septymą. Ich podobne symbole łatwo pomylić.','Zapisz Bm7♭5: B–D–F–A.|Porównaj Bdim7: B–D–F–A♭.|Zagraj oba jako arpeggia, następnie rozwiąż Bm7♭5–E7–Am.','m7♭5: 1 ♭3 ♭5 ♭7; dim7: 1 ♭3 ♭5 ♭♭7.','Nazwij różnicę i zagraj oba zbiory od B.','A♭ w Bdim7 jest zapisem septymy zmniejszonej, nie zwykłej seksty w nazwie akordu.','chordmap']],
 [8,'Jazz i bossa',['ii–V–i w moll','Improwizacja','Kadencja molowa często wykorzystuje dominantę z podwyższonym VII stopniem tonacji. W a-moll E7 wnosi G♯.','Zagraj kolejno składniki Bm7♭5, E7 i Am.|Zbuduj linię A–G♯–A przez trzy akordy.|Dodaj po jednym dźwięku poprzedzającym każdy cel i wykonaj cztery obiegi.','Bm7♭5: B D F A → E7: E G♯ B D → Am: A C E.','Zagraj cztery frazy z wyraźnym rozwiązaniem G♯→A.','Nie używaj G naturalnego jako przypadkowego celu nad E7.','minor']],
 [8,'Blues',['Chorus i turnaround','Improwizacja','W bluesie ostatnie takty prowadzą do początku kolejnego obiegu. Rozpoznawanie formy jest ważniejsze od liczby zagrywek.','Rozpisz 12 taktów bluesa w E z rozdziału 8.|Zagraj basy i licz głośno numery taktów.|Dodaj własną frazę w taktach 11–12, prowadzącą do E na początku następnego obiegu.','9:B7 · 10:A7 · 11:E7 · 12:B7 → 1:E7.','Wykonaj dwa chorusy bez pomylenia miejsca powrotu.','Nie kończ automatycznie po ośmiu taktach, gdy forma ma dwanaście.','intermediate']],
 [8,'Słuch i czytanie',['Transkrypcja basu','Słuch','Linia basowa ułatwia rozpoznanie harmonii, ale bas nie zawsze jest prymą. Najpierw odtwórz dźwięki, potem wnioskuj o akordach.','Wybierz cztery takty lekcji piosenki i słuchaj tylko basu.|Znajdź po jednej najniższej nucie na zmianę harmonii.|Porównaj z chwytami nauczyciela i zaznacz ewentualny przewrót.','Usłysz bas → znajdź nutę → sprawdź akord → nazwij przewrót.','Odtwórz bas czterech taktów i wyjaśnij jego relację do akordów.','Nie zgaduj nazwy akordu wyłącznie na podstawie jednej najniższej nuty.','inversions']],
 [9,'Jazz i bossa',['Bossa: dwa takty rytmu','Rytm','Bossa nova wymaga spokojnego, niezależnego basu. Ten wzór jest ćwiczeniem przygotowującym, nie jedynym poprawnym wzorem stylu.','Na Am7 graj bas na 1 i 3.|W takcie A dodaj akord na 1, „i” po 2 oraz 4.|W takcie B dodaj akord na „i” po 1, 3 oraz „i” po 4; ćwicz przy 45 BPM.','Bas zawsze 1 i 3; akordy zmieniają miejsca między taktami.','Zagraj cztery dwutaktowe cykle bez przesuwania basu.','Nie próbuj od razu grać w tempie nagrania z pełnymi trudnymi chwytami.','meter']],
 [9,'Jazz i bossa',['Dominanta poboczna','Teoria','Dominanta może na chwilę prowadzić do innego akordu niż tonika. W C-dur E7 prowadzi do Am, dlatego zawiera G♯ spoza skali C.','Porównaj C–Am–Dm–G z C–E7–Am–G.|Zaśpiewaj G♯→A przy przejściu E7–Am.|Dodaj taką dominantę do własnej czterotaktowej miniatury i porównaj wersje.','E7 = V/vi w C-dur; cel Am.','Zagraj obie wersje i nazwij dodatkowe napięcie.','Nie dodawaj dominanty bez sprawdzenia, czy nie koliduje z melodią.','cadences']],
 [9,'Fingerstyle',['Flażolet sztuczny: pojedynczy dźwięk','Technika','Dotyk dwanaście progów powyżej skróconej struny daje flażolet oktawowy. Prawa ręka jednocześnie dotyka węzła i szarpie strunę.','Przytrzymaj F na 1/1.|Prawym wskazującym dotknij nad XIII progiem, a innym palcem szarp strunę.|Odsuń dotyk i porównaj z flażoletem pustej struny nad XII.','Dźwięk zatrzymany na progu n → dotyk nad n+12.','Wydobądź trzy czyste flażolety F, bez ściskania prawej dłoni.','To opcjonalny kolor aranżacji; nie musi zastępować zwykłego dźwięku.','technique']],
 [10,'Klasyka',['Dwa głosy Bacha osobno','Repertuar','W kontrapunkcie bas jest drugą melodią. Ćwiczenie go osobno pozwala usłyszeć kierunek niezależny od góry.','Wybierz cztery takty Bourrée z darmowej lekcji.|Zagraj sam górny głos, następnie sam bas, zachowując zapisane długości.|Połącz je w wolnym tempie, wyróżniając raz górę, raz dół.','Głos górny → dolny → razem z różnym balansem.','Wykonaj oba głosy niezależnie i połącz cztery takty.','Nie skracaj każdej nuty basu do chwili następnego dźwięku melodii.','bach']],
 [10,'Fingerstyle',['Własna aranżacja w dwóch gęstościach','Repertuar','Dobra aranżacja może mieć wersję prostą i bogatszą. Obie muszą zachować melodię oraz formę.','Wybierz osiem taktów własnego chord melody.|Zagraj wersję sam bas i melodia.|Dodaj dwa ozdobniki oraz wypełnienia tylko pod długimi nutami i porównaj.','Wersja A: dwa głosy; wersja B: te same głosy plus wybrane wypełnienia.','Obie wersje są rozpoznawalne i mają ten sam puls.','Więcej nut nie zawsze daje lepszy rezultat muzyczny.','voicing']],
 [10,'Jazz i bossa',['Reharmonizacja pod melodią','Teoria','Nowy akord powinien współpracować z ważnym dźwiękiem melodii. Najpierw sprawdź ten dźwięk, dopiero potem efektowną nazwę chwytu.','Wybierz frazę kończącą się na E nad C.|Porównaj C, Am7 i Cmaj7 pod tym samym E.|Zagraj po dwa takty każdej wersji i zapisz, jak zmienił się kierunek harmoniczny.','E nad C = tercja; E nad Am7 = kwinta.','Zagraj trzy harmonizacje tej samej frazy i nazwij rolę E.','Nie zmieniaj akordów tak często, by melodia straciła punkt odniesienia.','voicing']],
];

const checkpointNames=['Pierwsza znana melodia','Piosenka przy ognisku','Riff albo pełny groove','Zagraj i wyjaśnij melodię','Znana piosenka, Twoja odpowiedź','Pierwszy repertuar palcami','Cała forma, swobodne chwyty','Solo słyszy harmonię','Twoje brzmienie na sześciu strunach','Utwór na finałowy występ'];
function fromRow(row:Row,id:string,chapter:number,optional=false,branch?:string):Lesson {
 const [title,category,theory,steps,example,criteria,mistake,source]=row;
 return {id,chapter,order:0,title,category,theory,steps:steps.split('|'),example,criteria:criteria.split('|'),mistake,source,prerequisites:[],optional,challenge:false,minutes:5,sessions:chapter<4?[2,4]:chapter<8?[3,6]:[4,8],branch};
}
export function expandCurriculum(original:Lesson[]):Lesson[]{
 const out:Lesson[]=[];
 for(let chapter=1;chapter<=10;chapter++){
  const prefix=String(chapter).padStart(2,'0');
  const old=original.filter(l=>l.chapter===chapter&&!l.optional);
  const additions=deep[chapter-1].map((r,i)=>fromRow(r,`deep-${prefix}-${i+1}`,chapter));
  const choices=repertoirePath.filter(s=>s.checkpoint===chapter).map(s=>s.id);
  const checkpoint:Lesson={id:`rep-${prefix}`,chapter,order:15,title:`Scena ${chapter}: ${checkpointNames[chapter-1]}`,category:'Repertuar',theory:'Wybierz jeden utwór w wersji opisanej poniżej. Nie musisz opanować wszystkich opcji. To zadanie na kilka sesji: ucz się fragmentów, łącz je i wróć do całości w innym dniu. Film jest pomocą, a sprawdzianem jest Twoje wykonanie.',steps:['Wybierz utwór i przeczytaj jego zakres: melodia, riff, akompaniament lub aranżacja to różne zadania.','Pracuj według planu utworu. Zapisuj tempo i trudne połączenia, zamiast za każdym razem zaczynać od początku.','Wykonaj kryteria utworu, wróć do niego w innym dniu i potwierdź gotowość do zaliczenia sceny.'],example:'Jedna wybrana wersja → praca nad fragmentem → całość → sprawdzenie w kolejnej sesji.',criteria:['Wykonałem dokładnie wskazany zakres wybranego utworu.','Powtórzyłem wykonanie w innym dniu i potrafię wskazać, co poprawiłem.'],mistake:'Nie zaliczaj pełnej piosenki po nauczeniu się samego intro. Gdy zadanie dotyczy riffu, zakres jest oznaczony wprost.',source:'marty',prerequisites:[],optional:false,challenge:true,minutes:7,sessions:chapter<4?[5,12]:chapter<8?[10,25]:chapter<10?[15,40]:[20,50],songChoices:choices};
  const sequence=[...old.slice(0,7),...additions,old[7],checkpoint];
  sequence.forEach((l,i)=>{l.order=i+1;l.sessions??=l.challenge?[3,6]:[2,4];l.prerequisites=i?[sequence[i-1].id]:chapter>1?[`rep-${String(chapter-1).padStart(2,'0')}`]:[];});
  out.push(...sequence);
  const legacySides=original.filter(l=>l.chapter===chapter&&l.optional);
  const newSides=side.filter(([c])=>c===chapter).map(([,branch,r],i)=>({...fromRow(r,`branch-${prefix}-${i+1}`,chapter,true,branch),order:i+3,prerequisites:[`ch-${prefix}-7`]}));
  out.push(...legacySides.map(l=>({...l,sessions:[2,5] as [number,number],branch:l.category==='Słuch'?'Słuch i czytanie':'Dodatkowa praktyka'})),...newSides);
 }
 return out;
}
